using System.Collections.Generic; using UnityEngine;
namespace PhumFarm.Data { [CreateAssetMenu(menuName="Phum Farm/Content Catalog", fileName="GameContentCatalog")] public sealed class GameContentCatalog : ScriptableObject { public List<ItemDefinitionAsset> items=new(); public List<CropDefinitionAsset> crops=new(); public List<AnimalDefinitionAsset> animals=new(); public List<RecipeDefinitionAsset> recipes=new(); public List<BuildingDefinitionAsset> buildings=new(); public List<ExpansionDefinitionAsset> expansions=new(); public List<LevelDefinitionAsset> levels=new(); public List<OrderDefinitionAsset> orders=new(); public List<QuestDefinitionAsset> quests=new(); public ItemDefinitionAsset Item(string id)=>items.Find(v=>v!=null&&v.id==id); public CropDefinitionAsset Crop(string id)=>crops.Find(v=>v!=null&&v.id==id); public AnimalDefinitionAsset Animal(string id)=>animals.Find(v=>v!=null&&v.id==id); public RecipeDefinitionAsset Recipe(string id)=>recipes.Find(v=>v!=null&&v.id==id); public BuildingDefinitionAsset Building(string id)=>buildings.Find(v=>v!=null&&v.id==id); public ExpansionDefinitionAsset Expansion(string id)=>expansions.Find(v=>v!=null&&v.id==id); } }
